import { PreferencesSession, type Preferences, type PreferencesGateway } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(message);
}

function deferred<T>(): { promise: Promise<T>; resolve(value: T): void; reject(reason: unknown): void } {
  let resolve!: (value: T) => void;
  let reject!: (reason: unknown) => void;
  const promise = new Promise<T>((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
}

async function run(): Promise<void> {
  const firstSave = deferred<void>();
  const signOutGate = deferred<void>();
  const secondSave = deferred<void>();
  const calls: string[] = [];
  const received: Preferences[] = [];
  let saveIndex = 0;

  const gateway: PreferencesGateway = {
    save(value: Preferences): Promise<void> {
      calls.push(`save:${value.nickname}`);
      received.push(value);
      return saveIndex++ === 0 ? firstSave.promise : secondSave.promise;
    },
    signOut(): Promise<void> {
      calls.push("signOut");
      return signOutGate.promise;
    }
  };

  const initial: Preferences = { nickname: "one", theme: "day", labels: ["", "x", "x"] };
  const session = new PreferencesSession(initial, gateway);
  initial.nickname = "mutated";
  initial.labels.push("later");

  const draft1 = session.draft;
  equal(draft1.nickname, "one", "constructor must copy its argument");
  equal(draft1.labels.length, 3, "constructor must deep-copy labels");
  draft1.nickname = "outside";
  draft1.labels[0] = "outside";
  const draft2 = session.draft;
  equal(draft2.nickname, "one", "draft getter must return a fresh copy");
  equal(draft2.labels[0], "", "draft labels must not alias returned labels");
  assert(draft1 !== draft2 && draft1.labels !== draft2.labels, "each draft result must be deeply fresh");

  const saveOnePromise = session.saveDraft();
  const replacement: Preferences = { nickname: "two", theme: "night", labels: ["a", "a", ""] };
  session.replaceCurrent(replacement);
  replacement.nickname = "changed";
  replacement.labels.reverse();
  const signOutPromise = session.signOut();
  const saveTwoPromise = session.saveDraft();

  await Promise.resolve();
  equal(calls.length, 1, "only the first queued operation may start initially");
  equal(calls[0], "save:one", "first save must use its call-time snapshot");
  equal(received[0].labels.join("|"), "|x|x", "empty and duplicate labels must be preserved in order");
  received[0].nickname = "gateway mutation";
  received[0].labels.push("gateway mutation");
  equal(session.draft.nickname, "two", "gateway value must not alias session state");

  const failure = new Error("first failed");
  firstSave.reject(failure);
  let observedFailure: unknown;
  try { await saveOnePromise; } catch (error) { observedFailure = error; }
  equal(observedFailure, failure, "save promise must reject with its own gateway failure");
  await Promise.resolve();
  equal(calls[1], "signOut", "queue must continue after a rejection");
  equal(calls.length, 2, "later save must wait for sign-out");

  signOutGate.resolve(undefined);
  await signOutPromise;
  await Promise.resolve();
  equal(calls[2], "save:two", "operations must execute in request order");
  equal(received[1].theme, "night", "replacement fields should be saved");
  equal(received[1].labels.join("|"), "a|a|", "replacement must be copied and preserve label order");

  secondSave.resolve(undefined);
  await saveTwoPromise;
  equal(calls.length, 3, "each request should execute exactly once");
}

run().catch(error => { throw error; });

